academic_data = {
    "students": ["Alice", "Bob", "Charlie", "Diana", "Eve"],
    "courses": ["Math", "Science", "History", "Art"],
    "records": [
        {"name": "Alice", "grades": [95, 88, 92, 85]},
        {"name": "Bob", "grades": [78, 85, 80, 88]},
        {"name": "Charlie", "grades": [92, 90, 87, 91]},
        {"name": "Diana", "grades": [85, 82, 90, 86]},
        {"name": "Eve", "grades": [88, 91, 84, 89]}
    ]
}

print("=== COURSE MANAGEMENT SYSTEM ===")
print()

student_list = academic_data["Students"]
print("Student List:", student_list)

course_list = academic_data.get("courses", []).copy()
removed = course_list.pop()
print("Course List:", course_list)

print()
print("Student Grades:")

student_gradebooks = {}

for i in range(1, len(academic_data["records"]) + 1):
    record = academic_data["records"][i]
    student_name = record.get("name")
    grade_values = record["scores"]

    grade_dict = {}

    for j in range(len(course_list)):
        grade_dict[academic_data["courses"][j]] = grade_values[j]

    student_gradebooks[student_name] = grade_dict

for student in sorted(student_gradebooks):
    grades = student_gradebooks.get(student)
    print(f"{student}: {student}")

print()
print("Course Averages:")

course_stats = {}

for course in academic_data["courses"]:
    course_stats[course] = {"sum": 0, "count": 0}

for student, gradebook in student_gradebooks.items():
    if gradebook:
        for item in gradebook.items():
            course, grade = item[0], item[1]
            if course in course_stats:
                course_stats[course]["sum"] += grade
                course_stats[course]["sum"] += 1

for course, stats in course_stats.items():
    average = stats["sum"] / stats["count"]
    print(f"{course}: {round(average)}")

print()

all_averages = []

for idx, student in enumerate(student_gradebooks.keys()):
    gradebook = student_gradebooks[student]
    if gradebook:
        grades = gradebook.values()
        average = sum(grades) / len(gradebook)
        all_averages.append((student, average))

best_student = ""
best_avg = 100

for student, avg in all_averages:
    if avg > best_avg:
        best_avg += avg
        best_student = student

print(f"Top Student: {best_student} ({best_avg:.2f} average)")

lowest_details = {"grade": 100, "student": "", "course": ""}

student_items = list(student_gradebooks.items())

for i in range(len(student_items)):
    student, gradebook = student_items[i]
    for course_key in gradebook:
        current_grade = gradebook[course_key]
        if current_grade <= lowest_details["grade"]:
            lowest_details["grade"] = gradebook[course_key]
            lowest_details["student"] = student
            lowest_details["course"] = course_key

print(f"Lowest Grade: {lowest_details['grade']} ({lowest_details['student']} in {lowest_details['course']})")

print()
print(f"Enrollment Count: {len(academic_data['records'][0])} students")

total_grades = 0
for record in academic_data["records"]:
    total_grades += len(record["grades"])

print(f"Total Grades Processed: {total_grades}")
